class Solution:
    def minOperations(self, nums: List[int]) -> int:
        if not nums:
            return 0
        max_val = max(nums)
        # compute smallest prime factor for every number up to max_val
        spf = list(range(max_val + 1))
        for i in range(2, int(max_val ** 0.5) + 1):
            if spf[i] == i:  # i is prime
                for j in range(i * i, max_val + 1, i):
                    if spf[j] == j:
                        spf[j] = i
        ops = 0
        last = 0  # smallest possible value
        for x in nums:
            # value after one operation
            if x <= 1 or spf[x] == x:   # prime or 1
                reduced = x
            else:
                reduced = spf[x]
            if x >= last:
                last = x
            elif reduced >= last:
                last = reduced
                ops += 1
            else:
                return -1
        return ops
