class Solution:
    MOD = 10**9 + 7

    def countKReducibleNumbers(self, s: str, k: int) -> int:
        nbits = len(s)
        max_pop = nbits  # maximum popcount for numbers < 2^nbits

        # Precompute binomial coefficients up to 800
        N = 800
        comb = [[0]*(N+1) for _ in range(N+1)]
        for i in range(N+1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % self.MOD

        # Precompute powers of 2
        pow2 = [1]*(N+1)
        for i in range(1, N+1):
            pow2[i] = pow2[i-1]*2 % self.MOD

        # Determine if a number with popcount t is reducible within k steps
        # We need to check after one operation: t -> popcount(t)
        # So we need chain length <= k-1 from t to 1
        from functools import lru_cache

        @lru_cache(None)
        def reducible(t, steps):
            # returns True if t can reach 1 within 'steps' operations
            if t == 1:
                return True
            if steps == 0:
                return False
            next_t = bin(t).count('1')
            return reducible(next_t, steps-1)

        # Precompute reducible[t] for all t <= max_pop
        reducible_arr = [False]*(max_pop+1)
        for t in range(1, max_pop+1):
            reducible_arr[t] = reducible(t, k-1)

        ans = 0

        # Count numbers with length < nbits
        for length in range(1, nbits):
            # MSB must be 1
            rem = length - 1
            for t in range(0, rem+1):
                popcnt = 1 + t
                if popcnt <= max_pop and reducible_arr[popcnt]:
                    ans = (ans + comb[rem][t]) % self.MOD

        # Count numbers with same length and < s
        used = 0  # popcount of prefix already fixed to match s
        for i, ch in enumerate(s):
            if ch == '1':
                # We can set this bit to 0, remaining bits arbitrary
                rem = nbits - i - 1
                for r in range(0, rem+1):
                    popcnt = used + r
                    if popcnt <= max_pop and reducible_arr[popcnt]:
                        ans = (ans + pow2[rem]) % self.MOD
                used += 1
            # if ch == '0', we just continue
        # Exclude 0 (not positive). Our counting never includes 0 because MSB must be 1 for lengths and when same length we only consider numbers with same prefix up to last bit; but when s itself is all zeros? impossible since no leading zeros.
        return ans % self.MOD
