    def hasMatch(self, s: str, p: str) -> bool:
        # Split pattern into prefix and suffix around the single '*'
        pre, post = p.split('*')
        n, m = len(s), len(p)
        lp, lp_len = len(pre), len(pre)
        ls, ls_len = len(post), len(post)

        # If both prefix and suffix are empty, any non‑empty substring matches
        if lp_len == 0 and ls_len == 0:
            return n > 0

        # Iterate over all possible starting positions of the prefix
        for i in range(n - lp_len + 1):
            if s[i:i+lp_len] != pre:
                continue

            # If suffix is empty, we only need the prefix to be present
            if ls_len == 0:
                return True

            # Now look for a suffix that starts at or after i + lp_len
            start_pos = i + lp_len
            max_start = n - ls_len
            for pos in range(start_pos, max_start + 1):
                if s[pos:pos+ls_len] == post:
                    return True

        return False
