class Solution:
    MOD = 10**9 + 7

    def countWinningSequences(self, s: str) -> int:
        n = len(s)
        # map move char to index 0:F,1:W,2:E
        move_idx = {'F':0, 'W':1, 'E':2}
        # precompute delta for each pair (alice, bob)
        # delta = +1 if Bob gets point, -1 if Alice gets point, 0 if tie
        delta = [[0]*3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a == b:
                    delta[a][b] = 0
                else:
                    # rules: F beats E, W beats F, E beats W
                    if (a==0 and b==2) or (a==1 and b==0) or (a==2 and b==1):
                        # Alice beats Bob
                        delta[a][b] = -1
                    else:
                        delta[a][b] = 1
        # DP[pos][last_move][score_offset] = count
        # score_offset from -n..n, shift by n
        offset = n
        dp = [[[0]*(2*n+1) for _ in range(3)] for _ in range(n+1)]
        # initialize first move
        a0 = move_idx[s[0]]
        for b in range(3):
            d = delta[a0][b]
            dp[1][b][d+offset] = 1
        # iterate positions
        for pos in range(1, n):
            a = move_idx[s[pos]]
            for last in range(3):
                for sc in range(2*n+1):
                    cnt = dp[pos][last][sc]
                    if cnt==0: continue
                    for nb in range(3):
                        if nb == last: continue
                        d = delta[a][nb]
                        ns = sc + d
                        if 0 <= ns < 2*n+1:
                            dp[pos+1][nb][ns] = (dp[pos+1][nb][ns] + cnt) % self.MOD
        # sum over final states with score > 0
        res = 0
        for last in range(3):
            for sc in range(offset+1, 2*n+1):
                res = (res + dp[n][last][sc]) % self.MOD
        return res
