from itertools import combinations

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {tuple(p) for p in points}
        max_area = -1

        # generate all pairs of distinct x coordinates and y coordinates
        xs = sorted(set(p[0] for p in points))
        ys = sorted(set(p[1] for p in points))

        for x1, x2 in combinations(xs, 2):
            for y1, y2 in combinations(ys, 2):
                # corners of the candidate rectangle
                c1 = (x1, y1)
                c2 = (x1, y2)
                c3 = (x2, y1)
                c4 = (x2, y2)
                if not (c1 in point_set and c2 in point_set and c3 in point_set and c4 in point_set):
                    continue

                # check no other point inside or on the border
                bad = False
                for p in points:
                    pt = tuple(p)
                    if pt in (c1, c2, c3, c4):
                        continue
                    if x1 <= pt[0] <= x2 and y1 <= pt[1] <= y2:
                        bad = True
                        break
                if bad:
                    continue

                area = abs((x2 - x1) * (y2 - y1))
                if area > max_area:
                    max_area = area

        return max_area
