class Solution:
    MOD = 10**9 + 7

    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        t = n - 1  # number of adjacent pairs
        if k > t:
            return 0

        # Precompute factorials and inverse factorials up to t
        fact = [1] * (t + 1)
        for i in range(1, t + 1):
            fact[i] = fact[i - 1] * i % self.MOD

        inv_fact = [1] * (t + 1)
        inv_fact[t] = pow(fact[t], self.MOD - 2, self.MOD)
        for i in range(t, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % self.MOD

        def comb(n, r):
            if r < 0 or r > n:
                return 0
            return fact[n] * inv_fact[r] % self.MOD * inv_fact[n - r] % self.MOD

        binom = comb(t, k)
        pow_term = pow(m - 1, t - k, self.MOD)
        return binom * m % self.MOD * pow_term % self.MOD
