from collections import defaultdict

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)
        count_k = nums.count(k)
        if count_k == n:
            return n

        # best[v] will store the maximum number of v's in a subarray that contains no k
        best = defaultdict(int)

        # current segment counters
        seg_counts = defaultdict(int)

        for num in nums:
            if num == k:
                # segment ends, update best
                for v, cnt in seg_counts.items():
                    if cnt > best[v]:
                        best[v] = cnt
                seg_counts.clear()
            else:
                seg_counts[num] += 1

        # last segment
        for v, cnt in seg_counts.items():
            if cnt > best[v]:
                best[v] = cnt

        bestmax = 0
        for v, cnt in best.items():
            if v != k:
                if cnt > bestmax:
                    bestmax = cnt

        return count_k + bestmax
