class Solution:
    def smallestNumber(self, n: int, t: int) -> int:
        """
        Returns the smallest integer >= n such that the product of its digits
        is divisible by t. Since n is small (<=100) and t <= 10, a simple
        linear search is sufficient.
        """
        def digit_product(x: int) -> int:
            prod = 1
            while x > 0:
                prod *= x % 10
                x //= 10
            return prod

        cur = n
        while True:
            if digit_product(cur) % t == 0:
                return cur
            cur += 1
