class Solution:
    def minimumSumSubarray(self, nums: list[int], l: int, r: int) -> int:
        n = len(nums)
        # prefix sums
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        best = None
        for start in range(n):
            # only consider lengths that keep us inside the array
            max_len = min(r, n - start)
            min_len = l
            if max_len < min_len:
                continue
            for length in range(min_len, max_len + 1):
                cur_sum = pref[start + length] - pref[start]
                if cur_sum > 0:
                    if best is None or cur_sum < best:
                        best = cur_sum
        return best if best is not None else -1
