import math

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        n = len(nums)
        # dp[a][b] = minimal sum after processing some prefix with a halvings and b subtractions used
        INF = 10**18
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for num in nums:
            newdp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            for a in range(op1 + 1):
                for b in range(op2 + 1):
                    cur = dp[a][b]
                    if cur == INF:
                        continue
                    # 1) do nothing
                    if cur + num < newdp[a][b]:
                        newdp[a][b] = cur + num
                    # 2) only halve
                    if a < op1:
                        halved = (num + 1) // 2
                        if cur + halved < newdp[a+1][b]:
                            newdp[a+1][b] = cur + halved
                    # 3) only subtract
                    if b < op2 and num >= k:
                        subbed = num - k
                        if cur + subbed < newdp[a][b+1]:
                            newdp[a][b+1] = cur + subbed
                    # 4) both operations (if allowed)
                    if a < op1 and b < op2 and num >= k:
                        # order doesn't matter for final value
                        after_sub = num - k
                        after_both = (after_sub + 1) // 2
                        if cur + after_both < newdp[a+1][b+1]:
                            newdp[a+1][b+1] = cur + after_both
            dp = newdp

        # answer is minimal sum over all allowed op counts
        ans = INF
        for a in range(op1 + 1):
            for b in range(op2 + 1):
                if dp[a][b] < ans:
                    ans = dp[a][b]
        return ans
