            S[d] = (S[d] + A[i][j]) % MOD

    zero_cnt = 0
    prod = 1
    for val in S:
        if val == 0:
            zero_cnt += 1
        else:
            prod = prod * val % MOD

    out_lines = []
    cur_h, cur_w = sh, sw
