class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # dp[day][city] = max points up to this day ending at city
        dp = [[0] * n for _ in range(k)]
        # day 0: start at any city and stay there
        for city in range(n):
            dp[0][city] = stayScore[0][city]
        # iterate over remaining days
        for day in range(1, k):
            for dest in range(n):
                # staying in dest
                best = dp[day-1][dest] + stayScore[day][dest]
                # moving from any other city
                for src in range(n):
                    if src == dest:
                        continue
                    val = dp[day-1][src] + travelScore[src][dest]
                    if val > best:
                        best = val
                dp[day][dest] = best
        # result is max over final day
        return max(dp[k-1])
