        # Compute prefix sums: pref[i] = sum(nums[0..i])
        pref = [0] * len(nums)
        pref[0] = nums[0]
        for i in range(1, len(nums)):
            pref[i] = pref[i-1] + nums[i]

        total = 0
        for i in range(len(nums)):
            start = max(0, i - nums[i])
            if start == 0:
                sub_sum = pref[i]
            else:
                sub_sum = pref[i] - pref[start-1]
