class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        INF = 10**9

        # check whether we can achieve max run length <= L with at most numOps flips
        def feasible(L: int) -> bool:
            # dp[bit][len] = minimal flips for processed prefix ending at current position
            dp_prev = [[INF] * (L + 1) for _ in range(2)]
            # initialize for position 0
            for b in (0, 1):
                flip = 0 if (s[0] == str(b)) else 1
                dp_prev[b][1] = flip

            for i in range(1, n):
                dp_cur = [[INF] * (L + 1) for _ in range(2)]
                for b in (0, 1):
                    flip = 0 if (s[i] == str(b)) else 1
                    for l in range(1, L + 1):
                        val = dp_prev[b][l]
                        if val >= INF:
                            continue
                        # extend current run
                        if l + 1 <= L:
                            if dp_cur[b][l + 1] > val + flip:
                                dp_cur[b][l + 1] = val + flip
                        # start new run with opposite bit
                        nb = 1 - b
                        if dp_cur[nb][1] > val + flip:
                            dp_cur[nb][1] = val + flip
                dp_prev = dp_cur

            # minimal flips over all ending states
            best = min(min(dp_prev[0]), min(dp_prev[1]))
            return best <= numOps

        # binary search smallest L
        lo, hi = 1, n
        ans = n
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans
