import sys
import math
from typing import List

class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0]*n

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            self.parent[ra] = rb
        else:
            self.parent[rb] = ra
            if self.rank[ra] == self.rank[rb]:
                self.rank[ra] += 1

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        idx = {v:i for i,v in enumerate(nums)}
        dsu = DSU(n)

        # numbers greater than threshold are isolated
        small_vals = [v for v in nums if v <= threshold]
        if not small_vals:
            return n

        present = [False]*(threshold+1)
        for v in small_vals:
            present[v] = True

        # build divisors list for all multiples up to threshold
        divs = [[] for _ in range(threshold+1)]
        for d in small_vals:
            for m in range(d, threshold+1, d):
                divs[m].append(d)

        # union all numbers that share a common multiple <= threshold
        for m in range(1, threshold+1):
            if len(divs[m]) <= 1:
                continue
            first = divs[m][0]
            for other in divs[m][1:]:
                dsu.union(idx[first], idx[other])

        # count distinct roots
        roots = set()
        for i in range(n):
            roots.add(dsu.find(i))
        return len(roots)
