import sys, math

def sieve(n):
    """Return list of primes <= n."""
    sieve = bytearray(b'\x01') * (n + 1)
    sieve[0:2] = b'\x00\x00'
    for p in range(2, int(n**0.5) + 1):
        if sieve[p]:
            step = p
            start = p*p
            sieve[start:n+1:step] = b'\x00' * (((n - start)//step) + 1)
    return [i for i, is_p in enumerate(sieve) if is_p]

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    M = math.isqrt(N)          # floor(sqrt(N))
    primes = sieve(M)
    # count primes^8
    cnt = 0
    for p in primes:
        if pow(p, 8) <= N:
            cnt += 1
        else:
            break
    # count distinct prime pairs p<q with p*q <= M
    pi = len(primes)
    j = pi - 1
    for i in range(pi):
        if j <= i:
            j = i + 1
        while j < pi and primes[i] * primes[j] > M:
            j -= 1
        if j <= i:
            break
        cnt += (j - i)
    print(cnt)

