import math
from heapq import heappush, heappop

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        # helper to test primality
        def is_prime(x: int) -> bool:
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            r = int(math.isqrt(x))
            for d in range(3, r + 1, 2):
                if x % d == 0:
                    return False
            return True

        # cannot start or finish at a prime
        if is_prime(n) or is_prime(m):
            return -1

        # same number of digits guaranteed, but we keep it
        digits = len(str(n))
        max_val = 10 ** digits - 1
        min_val = 10 ** (digits - 1)

        # Dijkstra: distance is cumulative sum of nodes visited
        dist = {}
        pq = []
        dist[n] = n  # cost includes start node
        heappush(pq, (n, n))  # (cost, node)

        while pq:
            cost, u = heappop(pq)
            if cost != dist[u]:
                continue
            if u == m:
                return cost
            s = str(u).zfill(digits)
            for i in range(digits):
                d = int(s[i])
                for delta in (-1, 1):
                    nd = d + delta
                    if 0 <= nd <= 9:
                        new_s = s[:i] + str(nd) + s[i+1:]
                        v = int(new_s)
                        if v < min_val or v > max_val:
                            continue
                        if is_prime(v):
                            continue
                        new_cost = cost + v
                        if v not in dist or new_cost < dist[v]:
                            dist[v] = new_cost
                            heappush(pq, (new_cost, v))
        return -1
