    H, W, D = map(int, input().split())
    grid = [list(input().strip()) for _ in range(H)]

    # distance array, -1 means not visited
    dist = [[-1] * W for _ in range(H)]
    q = deque()

    # initialize queue with all humidifier positions
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'H':
                dist[i][j] = 0
                q.append((i, j))

    # BFS
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while q:
        x, y = q.popleft()
        if dist[x][y] == D:
            continue  # cannot move further
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W:
                if grid[nx][ny] != '#' and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))

    # count humidified floor cells (including H cells)
    ans = 0
    for i in range(H):
        for j in range(W):
            if dist[i][j] != -1 and grid[i][j] != '#':
                ans += 1

    print(ans)

