def ceil_div(a, b):
    return (a + b - 1) // b

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        N = int(next(it))
    except StopIteration:
        return
    X = int(next(it))
    A = [0]*N
    P = [0]*N
    B = [0]*N
    Q = [0]*N
    for i in range(N):
        A[i] = int(next(it)); P[i] = int(next(it))
        B[i] = int(next(it)); Q[i] = int(next(it))

    # Upper bound for answer
    # minimal cost per unit for each process
    sum_min_unit_cost = 0.0
    for i in range(N):
        cost_s = P[i] / A[i]
        cost_t = Q[i] / B[i]
        sum_min_unit_cost += min(cost_s, cost_t)
    if sum_min_unit_cost == 0:
        high = 10**18
    else:
        high = int(X / sum_min_unit_cost) + 1

    def can(w: int) -> bool:
        total = 0
        for i in range(N):
            ai, pi, bi, qi = A[i], P[i], B[i], Q[i]
            best = 10**18
            # iterate over k
            max_k = min(ceil_div(w, ai), bi)
            for k in range(max_k + 1):
                rem = w - k * ai
                if rem <= 0:
                    cost = k * pi
                else:
                    l = ceil_div(rem, bi)
                    cost = k * pi + l * qi
                if cost < best:
                    best = cost
            # iterate over l
            max_l = min(ceil_div(w, bi), ai)
            for l in range(max_l + 1):
                rem = w - l * bi
                if rem <= 0:
                    cost = l * qi
                else:
                    k = ceil_div(rem, ai)
                    cost = k * pi + l * qi
                if cost < best:
                    best = cost
            total += best
            if total > X:
                return False
        return total <= X

    low, high = 0, high
    while low < high:
        mid = (low + high + 1) // 2
        if can(mid):
            low = mid
        else:
            high = mid - 1
    print(low)

